// QueryBool returns the bool value of the query string parameter.
// If the parameter is missing, empty, or not parsable as a boolean,
// it returns the default value (true if no default is provided).
//
//	GET /?want_pizza=false&id=
//	QueryBool("want_pizza") == false
//	QueryBool("want_pizza", true) == false
//	QueryBool("unknown") == true
//	QueryBool("unknown", false) == false
//	QueryBool("id") == true
//	QueryBool("id", false) == false
func (c *Ctx) QueryBool(key string, defaultValue ...bool) bool {
	raw := c.app.getString(c.fasthttp.QueryArgs().Peek(key))
	if raw == "" {
		if len(defaultValue) > 0 {
			return defaultValue[0]
		}
		return true
	}

	value, err := strconv.ParseBool(raw)
	if err != nil {
		if len(defaultValue) > 0 {
			return defaultValue[0]
		}
		return true
	}

	return value
}

// QueryFloat returns the float64 value of the query string parameter.
// If the parameter is missing, empty, or not parsable as a float,
// it returns the default value (0 if no default is provided).
//
//	GET /?amount=32.23&name=alex&id=
//	QueryFloat("amount") == 32.23
//	QueryFloat("amount", 0.5) == 32.23
//	QueryFloat("name") == 0
//	QueryFloat("name", 0.5) == 0.5
//	QueryFloat("id") == 0
//	QueryFloat("id", 0.5) == 0.5
func (c *Ctx) QueryFloat(key string, defaultValue ...float64) float64 {
	raw := c.app.getString(c.fasthttp.QueryArgs().Peek(key))
	if raw == "" {
		if len(defaultValue) > 0 {
			return defaultValue[0]
		}
		return 0
	}

	value, err := strconv.ParseFloat(raw, 64)
	if err != nil {
		if len(defaultValue) > 0 {
			return defaultValue[0]
		}
		return 0
	}

	return value
}

