func GetMIME(extension string) string {
	if len(extension) == 0 {
		return ""
	}
	var mimeType string
	if extension[0] == '.' {
		mimeType = mimeExtensions[extension[1:]]
	} else {
		mimeType = mimeExtensions[extension]
	}
	if len(mimeType) == 0 {
		// Try standard library's mime.TypeByExtension as fallback
		if extension[0] != '.' {
			extension = "." + extension
		}
		mimeType = mime.TypeByExtension(extension)
		if mimeType == "" {
			return MIMEOctetStream
		}
	}
	return mimeType
}

