package fiber

import (
	"crypto/tls"
	"io"
	"net/http/httptest"
	"testing"
	"time"

	"github.com/gofiber/fiber/v2/middleware/cors"
	"github.com/gofiber/fiber/v2/middleware/requestid"
	"github.com/gofiber/fiber/v2/middleware/session"
	"github.com/gofiber/fiber/v2/utils"
)

// Test 1: QueryBool and QueryFloat
func TestCtx_QueryBool(t *testing.T) {
	app := New()
	app.Get("/", func(c *Ctx) error {
		return c.SendString(utils.ToString(c.QueryBool("enabled")))
	})

	tests := []struct {
		url      string
		expected string
	}{
		{"/", "true"},                    // missing, default true
		{"/?enabled=true", "true"},       // explicit true
		{"/?enabled=false", "false"},     // explicit false
		{"/?enabled=1", "true"},          // 1 = true
		{"/?enabled=0", "false"},         // 0 = false
		{"/?enabled=invalid", "true"},    // invalid, default true
	}

	for _, tt := range tests {
		req := httptest.NewRequest("GET", tt.url, nil)
		resp, _ := app.Test(req)
		body, _ := io.ReadAll(resp.Body)
		if string(body) != tt.expected {
			t.Errorf("QueryBool(%s): expected %s, got %s", tt.url, tt.expected, string(body))
		}
	}
}

func TestCtx_QueryFloat(t *testing.T) {
	app := New()
	app.Get("/", func(c *Ctx) error {
		return c.SendString(utils.ToString(c.QueryFloat("price")))
	})

	tests := []struct {
		url      string
		expected string
	}{
		{"/", "0"},                       // missing, default 0
		{"/?price=19.99", "19.99"},       // valid float
		{"/?price=100", "100"},           // integer as float
		{"/?price=invalid", "0"},         // invalid, default 0
	}

	for _, tt := range tests {
		req := httptest.NewRequest("GET", tt.url, nil)
		resp, _ := app.Test(req)
		body, _ := io.ReadAll(resp.Body)
		if string(body) != tt.expected {
			t.Errorf("QueryFloat(%s): expected %s, got %s", tt.url, tt.expected, string(body))
		}
	}
}

// Test 4: CORS wildcard with credentials
func TestCORS_WildcardWithCredentials(t *testing.T) {
	app := New()

	app.Use(cors.New(cors.Config{
		AllowOrigins:     "*",
		AllowCredentials: true,
	}))

	app.Get("/", func(c *Ctx) error {
		return c.SendString("ok")
	})

	req := httptest.NewRequest("GET", "/", nil)
	req.Header.Set("Origin", "https://example.com")
	resp, _ := app.Test(req)

	// With credentials, should use actual origin, not "*"
	origin := resp.Header.Get("Access-Control-Allow-Origin")
	if origin != "https://example.com" {
		t.Errorf("CORS: expected origin 'https://example.com', got '%s'", origin)
	}
}

// Test 5: RequestID ContextKey as interface{}
func TestRequestID_ContextKeyInterface(t *testing.T) {
	app := New()

	type customKey struct{}

	app.Use(requestid.New(requestid.Config{
		ContextKey: customKey{},
	}))

	app.Get("/", func(c *Ctx) error {
		val := c.Locals(customKey{})
		if val == nil {
			return c.SendString("not found")
		}
		return c.SendString(val.(string))
	})

	req := httptest.NewRequest("GET", "/", nil)
	resp, _ := app.Test(req)
	body, _ := io.ReadAll(resp.Body)

	// Should find the request ID stored with custom key
	if string(body) == "not found" {
		t.Error("RequestID: ContextKey as interface{} not working")
	}
}

// Test 5: RequestID Generator optimization (only called when needed)
func TestRequestID_GeneratorOptimization(t *testing.T) {
	app := New()

	callCount := 0
	app.Use(requestid.New(requestid.Config{
		Generator: func() string {
			callCount++
			return "generated-id"
		},
	}))

	app.Get("/", func(c *Ctx) error {
		return c.SendString("ok")
	})

	// Request with existing header - generator should NOT be called
	req := httptest.NewRequest("GET", "/", nil)
	req.Header.Set("X-Request-ID", "existing-id")
	app.Test(req)

	if callCount != 0 {
		t.Errorf("RequestID: Generator called %d times when header present (expected 0)", callCount)
	}

	// Request without header - generator should be called
	req2 := httptest.NewRequest("GET", "/", nil)
	app.Test(req2)

	if callCount != 1 {
		t.Errorf("RequestID: Generator called %d times when header missing (expected 1)", callCount)
	}
}

// Test 6: CookieSessionOnly
func TestSession_CookieSessionOnly(t *testing.T) {
	app := New()

	store := session.New(session.Config{
		CookieSessionOnly: true,
	})

	app.Get("/set", func(c *Ctx) error {
		sess, _ := store.Get(c)
		sess.Set("key", "value")
		sess.Save()
		return c.SendString("ok")
	})

	req := httptest.NewRequest("GET", "/set", nil)
	resp, _ := app.Test(req)

	// Check Set-Cookie header doesn't contain Max-Age or Expires
	cookies := resp.Header.Values("Set-Cookie")
	if len(cookies) == 0 {
		t.Error("Session: No cookie set")
		return
	}

	cookie := cookies[0]
	if utils.Contains(cookie, "Max-Age") || utils.Contains(cookie, "Expires") {
		t.Errorf("Session: CookieSessionOnly should not set Max-Age or Expires, got: %s", cookie)
	}
}

// Test 7: GetMIME with mime.TypeByExtension fallback
func TestGetMIME_Fallback(t *testing.T) {
	// Test with an extension not in mimeExtensions map but in standard library
	mime := utils.GetMIME(".go")
	if mime == "application/octet-stream" {
		t.Error("GetMIME: Should use mime.TypeByExtension fallback for .go files")
	}

	// Test unknown extension returns octet-stream
	mime2 := utils.GetMIME(".unknown-ext-12345")
	if mime2 != "application/octet-stream" {
		t.Errorf("GetMIME: Unknown extension should return octet-stream, got %s", mime2)
	}
}

// Test 3: ListenTLSWithCertificate (structure test only, not actual server)
func TestListenTLSWithCertificate_Exists(t *testing.T) {
	app := New()

	// Create a dummy certificate for testing
	cert := tls.Certificate{}

	// This will fail to bind but proves the method exists and accepts tls.Certificate
	err := app.ListenTLSWithCertificate(":0", cert)
	if err == nil {
		t.Error("Expected error with empty certificate")
	}
}

// Test 3: ListenMutualTLSWithCertificate (structure test only)
func TestListenMutualTLSWithCertificate_Exists(t *testing.T) {
	app := New()

	// Create dummy certificates for testing
	serverCert := tls.Certificate{}
	clientCert := tls.Certificate{}

	// This will fail to bind but proves the method exists
	err := app.ListenMutualTLSWithCertificate(":0", serverCert, clientCert)
	if err == nil {
		t.Error("Expected error with empty certificates")
	}
}

