	req = httptest.NewRequest("GET", "/test?enabled=false&premium=true", nil)
	resp, _ = app.Test(req)
	body, _ = io.ReadAll(resp.Body)
	if !utils.Contains(string(body), `"enabled":false`) {
		t.Errorf("QueryBool should parse false, got: %s", body)
